package com.integrydt.backend.controller;
import com.integrydt.backend.security.AuthenticatedUser;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/devices") @PreAuthorize("hasAuthority('PERM_devices.read')") public class DevicesController {private final JdbcTemplate db;public DevicesController(JdbcTemplate d){db=d;}@GetMapping public Object list(Authentication a){String c=((AuthenticatedUser)a.getPrincipal()).companyId();return db.queryForList("SELECT CAST(id AS CHAR) id,name,machine_key machineKey,os,architecture,agent_version agentVersion,status,last_seen_at lastSeenAt,created_at createdAt FROM devices WHERE company_id=? ORDER BY name",c);}}
